const { useState } = React;

function App() {
  const [n, setN] = useState(0);
  return (
    <div style={{textAlign:"center",fontFamily:"sans-serif",marginTop:40}}>
      <h1>React</h1>
      <div style={{fontSize:48}}>{n}</div>
      <button onClick={() => setN(n + 1)}>+1</button>
    </div>
  );
}

